from binascii import unhexlify
import base64

def decode_hex_to_readable(hex_string):
    # Ensure the string length is even for unhexlify
    if len(hex_string) % 2 != 0:
        hex_string = "0" + hex_string

    # Convert hex string to bytes
    try:
        byte_data = unhexlify(hex_string)
        print("Decoded bytes:", byte_data)

        # Attempt ASCII decoding
        try:
            ascii_decoded = byte_data.decode('ascii')
            print("ASCII Decoded:", ascii_decoded)
        except UnicodeDecodeError:
            print("ASCII Decoding failed")

        # Attempt UTF-8 decoding
        try:
            utf8_decoded = byte_data.decode('utf-8')
            print("UTF-8 Decoded:", utf8_decoded)
        except UnicodeDecodeError:
            print("UTF-8 Decoding failed")

        # Attempt Base64 decoding
        try:
            base64_decoded = base64.b64decode(byte_data).decode('utf-8')
            print("Base64 Decoded:", base64_decoded)
        except Exception:
            print("Base64 Decoding failed")

    except Exception as e:
        print("Error during decoding:", e)

if __name__ == "__main__":
    hex_representation = "16554e04ee0830f283f2dbf9ceef1a2afe7f093d1634db10e41ff520fec2d2712ea42ac96acae66"
